#!/usr/bin/env bash
# AKFC — « S'inscrire » : placement, retour accueil, ajout de partenaire.
#  - l'entrée « S'inscrire » quitte la barre de navigation ; la page reste accessible depuis le
#    bouton « Comment s'inscrire » de l'accueil, un encart en tête de la page Contacts et la
#    colonne « Le site » du pied de page.
#  - lien « ← Accueil » en haut de la page « S'inscrire ».
#  - Réglages → Partenaires : l'erreur de chargement et l'erreur d'ajout s'affichent (avant :
#    silencieuses) ; la fiche créée est amenée à l'écran, encadrée, avec la marche à suivre.
#  Preuve avant commit : pnpm check (sinon TOUT est restauré).
# Usage : bash fix-inscription-placement.sh   (AKFC_APPLY_ONLY=1 : applique sans vérifier ni committer)
set -euo pipefail
[ -f "package.json" ] || { echo "ERREUR: racine du repo." >&2; exit 1; }
FILES=(apps/web/src/features/app-shell/navEntries.ts apps/web/src/features/app-shell/Footer.tsx "apps/web/src/app/(public)/contacts/page.tsx" "apps/web/src/app/(public)/inscription/page.tsx" apps/web/src/features/admin/site-settings/PartnersSettings.tsx)
[ -f "${FILES[3]}" ] || { echo "ERREUR: applique d'abord apply-site-partners-front.sh et fix-inscription-online.sh." >&2; exit 1; }
grep -q "Vous souhaitez vous inscrire" "${FILES[2]}" && { echo "— déjà appliqué"; exit 0; }
BK=/tmp/akfc_place_backup; rm -rf "$BK"; mkdir -p "$BK"
for f in "${FILES[@]}"; do mkdir -p "$BK/$(dirname "$f")"; cp "$f" "$BK/$f"; done
restore(){ for f in "${FILES[@]}"; do cp "$BK/$f" "$f"; done; echo "↩ fichiers restaurés à l'identique (aucun commit)."; }
W=/tmp/akfc_place; rm -rf "$W"; mkdir -p "$W"
echo '' | base64 -d > "$W/edit.py"
echo "== application =="
python3 "$W/edit.py" . || { restore; exit 1; }
if [ "${AKFC_APPLY_ONLY:-0}" = "1" ]; then echo "APPLY_ONLY"; exit 0; fi
echo "== pnpm check =="
if ! pnpm check > /tmp/akfc_tc.log 2>&1; then
  echo "❌ check ÉCHOUÉ :"; grep -nE "conventions Next|error TS|Error:" /tmp/akfc_tc.log | head -15; restore; exit 1
fi
echo "  ✅ check OK"
git add "${FILES[@]}"
git commit -F - >/tmp/c.log 2>&1 <<'MSG' && echo "✅ commit $(git rev-parse --short HEAD)" || { echo "commit KO"; tail -3 /tmp/c.log; }
fix(inscription): hors navbar (accueil, Contacts, pied de page), retour accueil, ajout de partenaire visible

